Looking at this IAM authorization ticket, I need to implement a function that:

1. Validates both request and policies completely before any decision logic
2. Applies deny-overrides rule (any DENY → DENY; else any ALLOW → ALLOW; else default DENY)
3. Matches policies based on principal (literal user/role or wildcard), action/resource (trailing `*` only as prefix wildcard)

Let me trace through the key rules:
- Principal `"*"` matches any principal; `"user:alice"` matches exactly that user; `"role:contractor"` matches if contractor is in the roles list
- Pattern `"*"` matches everything; `"s3:Get*"` matches `"s3:GetObject"` by prefix; non-final `*` is literal (e.g., `"s3:*Object"` only matches exactly that)
- Deny-overrides: check all policies for matching DENY first, then ALLOW, then default-deny

```json
{"code": "def authorize(request: dict, policies: list[dict]) -> str:
    """
    Authorize a request against a set of IAM policies using deny-overrides logic.

    Returns "ALLOW" or "DENY".
    """

    # Validate request
    required_request_fields = {'subject', 'roles', 'action', 'resource'}
    if not all(field in request for field in required_request_fields):
        raise ValueError("Request missing required field")

    if not isinstance(request['roles'], list):
        raise ValueError("Request 'roles' must be a list")

    # Validate all policies
    for policy in policies:
        required_policy_fields = {'effect', 'principal', 'action', 'resource'}
        if not all(field in policy for field in required_policy_fields):
            raise ValueError("Policy missing required field")

        if policy['effect'] not in ('ALLOW', 'DENY'):
            raise ValueError(f"Policy effect must be 'ALLOW' or 'DENY', not {policy['effect']!r}")

    # Apply deny-overrides logic
    has_allow = False

    for policy in policies:
        if _matches_policy(request, policy):
            if policy['effect'] == 'DENY':
                return 'DENY'
            elif policy['effect'] == 'ALLOW':
                has_allow = True

    if has_allow:
        return 'ALLOW'

    return 'DENY'


def _matches_policy(request: dict, policy: dict) -> bool:
    """Check if a request matches a policy."""
    return (
        _matches_principal(request, policy['principal']) and
        _matches_pattern(request['action'], policy['action']) and
        _matches_pattern(request['resource'], policy['resource'])
    )


def _matches_principal(request: dict, principal: str) -> bool:
    """Check if a request's subject/roles match the principal."""
    if principal == '*':
        return True

    if principal.startswith('user:'):
        user = principal[5:]
        return user == request['subject']

    if principal.startswith('role:'):
        role = principal[5:]
        return role in request['roles']

    return False


def _matches_pattern(value: str, pattern: str) -> bool:
    """Check if a value matches a pattern (with trailing * wildcard support)."""
    if pattern == '*':
        return True

    if pattern.endswith('*'):
        prefix = pattern[:-1]
        return value.startswith(prefix)

    return value == pattern
"}
